const net = require('net');
const crypto = require('crypto');
const ldap = require('ldapjs');

const ENCRYPTION_KEY = crypto.randomBytes(32);
const IV_LENGTH = 16;
const MAX_ATTR_KEY_LENGTH = 256;
const MAX_ATTR_VALUE_LENGTH = 1024;

function encrypt(text) {
  const iv = crypto.randomBytes(IV_LENGTH);
  const cipher = crypto.createCipheriv('aes-256-gcm', ENCRYPTION_KEY, iv);
  let encrypted = cipher.update(text, 'utf8', 'hex');
  encrypted += cipher.final('hex');
  const tag = cipher.getAuthTag().toString('hex');
  return iv.toString('hex') + ':' + encrypted + ':' + tag;
}

function decrypt(text) {
  const parts = text.split(':');
  if (parts.length !== 3) throw new Error('Invalid encrypted format');
  const iv = Buffer.from(parts[0], 'hex');
  const encryptedText = parts[1];
  const tag = Buffer.from(parts[2], 'hex');
  const decipher = crypto.createDecipheriv('aes-256-gcm', ENCRYPTION_KEY, iv);
  decipher.setAuthTag(tag);
  let decrypted = decipher.update(encryptedText, 'hex', 'utf8');
  decrypted += decipher.final('utf8');
  return decrypted;
}

class CredentialStore {
  constructor() {
    this.store = new Map();
  }

  save(sessionId, credentials) {
    const payload = JSON.stringify(credentials);
    this.store.set(sessionId, encrypt(payload));
  }

  retrieve(sessionId) {
    const encrypted = this.store.get(sessionId);
    if (!encrypted) return null;
    return JSON.parse(decrypt(encrypted));
  }
}

class LDAPQueryBuilder {
  constructor() {
    this.specialChars = ['\\', '*', '(', ')', '\0'];
    this.replacements = ['\\5c', '\\2a', '\\28', '\\29', '\\00'];
  }

  sanitizeComponent(input) {
    if (typeof input !== 'string') return '';
    let sanitized = input;
    for (let i = 0; i < this.specialChars.length; i++) {
      sanitized = sanitized.split(this.specialChars[i]).join(this.replacements[i]);
    }
    return sanitized;
  }

  buildSearchFilter(attributes) {
    const parts = [];
    for (const [key, value] of Object.entries(attributes)) {
      const safeKey = this.sanitizeComponent(key);
      const safeValue = this.normalizeValue(value);
      parts.push(`(${safeKey}=${safeValue})`);
    }
    if (parts.length === 1) return parts[0];
    return `(&${parts.join('')})`;
  }

  normalizeValue(value) {
    if (typeof value === 'number') return String(value);
    if (typeof value === 'boolean') return value ? 'TRUE' : 'FALSE';
    if (typeof value === 'string') {
      return this.processStringValue(value);
    }
    return '';
  }

  processStringValue(value) {
    return this.sanitizeComponent(value);
  }
}

class ProxyServer {
  constructor(ldapUrl, baseDN) {
    this.ldapUrl = ldapUrl;
    this.baseDN = baseDN;
    this.credStore = new CredentialStore();
    this.queryBuilder = new LDAPQueryBuilder();
    this.server = net.createServer(this.handleConnection.bind(this));
  }

  handleConnection(socket) {
    let buffer = '';
    socket.on('data', (data) => {
      buffer += data.toString();
      if (buffer.length > 65536) {
        socket.destroy();
        return;
      }
      if (buffer.includes('\n')) {
        const lines = buffer.split('\n');
        buffer = lines.pop();
        lines.forEach(line => this.processRequest(socket, line));
      }
    });
  }

  async processRequest(socket, rawLine) {
    try {
      const request = JSON.parse(rawLine);
      if (request.action === 'search') {
        await this.handleSearch(socket, request);
      } else if (request.action === 'auth') {
        await this.handleAuth(socket, request);
      }
    } catch (e) {
      socket.write(JSON.stringify({ error: 'Invalid request' }) + '\n');
    }
  }

  async handleAuth(socket, request) {
    if (typeof request.dn !== 'string' || typeof request.password !== 'string') {
      socket.write(JSON.stringify({ error: 'Invalid credentials format' }) + '\n');
      return;
    }
    const sessionId = crypto.randomUUID();
    this.credStore.save(sessionId, { dn: request.dn, password: request.password });
    socket.write(JSON.stringify({ sessionId }) + '\n');
  }

  async handleSearch(socket, request) {
    const { sessionId, attributes } = request;
    if (!sessionId || typeof attributes !== 'object' || attributes === null || Array.isArray(attributes)) {
      socket.write(JSON.stringify({ error: 'Invalid request format' }) + '\n');
      return;
    }

    for (const [key, value] of Object.entries(attributes)) {
      if (typeof key !== 'string' || typeof value !== 'string') {
        socket.write(JSON.stringify({ error: 'Attributes must be string key-value pairs' }) + '\n');
        return;
      }
      if (key.length > MAX_ATTR_KEY_LENGTH || value.length > MAX_ATTR_VALUE_LENGTH) {
        socket.write(JSON.stringify({ error: 'Attribute key or value exceeds maximum allowed length' }) + '\n');
        return;
      }
    }

    const creds = this.credStore.retrieve(sessionId);
    if (!creds) {
      socket.write(JSON.stringify({ error: 'Unauthorized' }) + '\n');
      return;
    }

    const filter = this.queryBuilder.buildSearchFilter(attributes);
    const client = ldap.createClient({ url: this.ldapUrl });

    client.bind(creds.dn, creds.password, (err) => {
      if (err) {
        socket.write(JSON.stringify({ error: 'Bind failed' }) + '\n');
        client.unbind();
        return;
      }

      const opts = { filter, scope: 'sub', attributes: ['dn', 'cn', 'mail'] };
      client.search(this.baseDN, opts, (err, res) => {
        const results = [];
        if (err) {
          socket.write(JSON.stringify({ error: 'Search failed' }) + '\n');
          client.unbind();
          return;
        }
        res.on('searchEntry', (entry) => results.push(entry.pojo));
        res.on('end', () => {
          socket.write(JSON.stringify({ results }) + '\n');
          client.unbind();
        });
      });
    });
  }

  listen(port) {
    this.server.listen(port, () => console.log(`Proxy on port ${port}`));
  }
}

const proxy = new ProxyServer('ldap://directory.internal:389', 'dc=corp,dc=local');
proxy.listen(8389);

module.exports = { ProxyServer, LDAPQueryBuilder, CredentialStore, encrypt, decrypt };
